[
  {
    "statement": "The success of providing artificial nest sites differs significantly between solitary bees and bumblebees.",
    "citations": []
  },
  {
    "statement": "Solitary bees show much higher success rates in occupying artificial nest sites than bumblebees do.",
    "citations": []
  },
  {
    "statement": "For solitary bees, 29 out of 30 replicated trials showed occupancy by bees across 10 countries, including Europe, North and South America, and Asia.",
    "citations": [
      "47"
    ]
  },
  {
    "statement": "Reported occupancy rates for solitary bee nest boxes were between 1% and 26% of available cavities.",
    "citations": [
      "80"
    ]
  },
  {
    "statement": "The number of occupied solitary bee nests can double over three years with repeated nest box provision at a given site.",
    "citations": [
      "47"
    ]
  },
  {
    "statement": "The doubling of occupied solitary bee nests was demonstrated in three trials on agricultural land.",
    "citations": [
      "47"
    ]
  },
  {
    "statement": "One study estimated that the number of foraging Osmia bees had increased in fields with nest boxes compared to fields without nest boxes.",
    "citations": [
      "47"
    ]
  },
  {
    "statement": "In contrast to solitary bees, bumblebee nest box success is much lower.",
    "citations": []
  },
  {
    "statement": "Three replicated trials since 1989 in the UK showed very low uptake rates of 0-2.5% for various bumblebee nest box designs.",
    "citations": [
      "48"
    ]
  },
  {
    "statement": "Seven earlier trials in the UK, USA, or Canada showed overall bumblebee nest box uptake rates between 10% and 48%.",
    "citations": [
      "48"
    ]
  },
  {
    "statement": "Two replicated trials that tested bumblebee nest boxes both found very low uptake of 2% or less.",
    "citations": [
      "80"
    ]
  },
  {
    "statement": "Underground nest boxes buried 5-10 cm underground with entrance pipes are generally the most effective for bumblebees.",
    "citations": [
      "48"
    ]
  },
  {
    "statement": "Seven replicated trials of underground bumblebee nest boxes found between 6% and 58% occupancy.",
    "citations": [
      "48"
    ]
  },
  {
    "statement": "The occupancy rates for even the most effective bumblebee nest boxes are often lower than solitary bee success rates.",
    "citations": [
      "48"
    ]
  },
  {
    "statement": "There is no evidence captured for the effects of providing nest boxes on bumblebee populations.",
    "citations": [
      "48"
    ]
  }
]

[
  {
    "statement": "Several actions related to reducing farming intensity can benefit wild bees.",
    "citations": []
  },
