[
  {
    "statement": "Documented risks and negative impacts are associated with artificial nest and bee reintroduction interventions.",
    "citations": []
  },
  {
    "statement": "For artificial nest sites for solitary bees, eleven replicated trials recorded attacks by parasites or predators.",
    "citations": [
      "47"
    ]
  },
  {
    "statement": "Mortality rates from parasite or predator attacks on artificial nest sites ranged from 13% for cavity-nesting bees and wasps in Germany to 56% for the subtropical carpenter bee Xylocopa fenestrata in India.",
    "citations": [
      "47"
    ]
  },
  {
    "statement": "Nest boxes with plastic-lined holes, or plastic or paper tubes, were much less productive due to parasitism or mould.",
    "citations": [
      "47"
    ]
